import SwiftUI
struct Book: Identifiable { let id: UUID; var title: String }
struct LibraryView: View {
    @State private var books: [Book] = []
    @State private var selectedBook: Book?
    @State private var showEditor = false
    @State private var showDelete = false
    var body: some View {
        List(books) { book in
            HStack {
                Text(book.title)
                Button("编辑") {
                    showEditor = true
                    selectedBook = book
                }
                Button("删除") {
                    selectedBook = book
                    showDelete = true
                }
            }
        }
        .sheet(isPresented: $showEditor) {
            if let book = selectedBook { Text("编辑：" + book.title) }
        }
        .alert("删除这本书？", isPresented: $showDelete) {
            Button("删除", role: .destructive) {
                books.removeAll { $0.id == selectedBook?.id }
            }
            Button("取消", role: .cancel) { }
        }
    }
}

