def summarize_windows(events):
    rows = sorted(events, key=lambda row: row["time"])
    totals = {}
    for row in rows:
        if row["kind"] == "usage":
            used = row["after"] - row["before"]
            totals[row["pool"]] = totals.get(row["pool"], 0) + max(0, used)
    return totals

