import unittest
from meter import summarize_windows
class MeterTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(summarize_windows([{"time":1,"kind":"usage","pool":"weekly","before":10,"after":12,"valid":True}]), {"weekly":2})
    def test_invalid(self):
        self.assertEqual(summarize_windows([{"time":1,"kind":"usage","pool":"weekly","before":10,"after":12,"valid":False}]), {})
    def test_reset(self):
        self.assertEqual(summarize_windows([{"time":1,"kind":"reset","pool":"weekly","before":98,"after":0,"valid":True}]), {})
    def test_crossing_reset(self):
        self.assertEqual(summarize_windows([{"time":1,"kind":"usage","pool":"weekly","before":98,"after":2,"valid":True}]), {})
    def test_default_valid(self):
        self.assertEqual(summarize_windows([{"time":1,"kind":"usage","pool":"five_hour","before":1,"after":4}]), {"five_hour":3})
    def test_missing_time(self):
        self.assertEqual(summarize_windows([{"kind":"usage","pool":"weekly","before":1,"after":2}]), {"weekly":1})
    def test_multi_pool(self):
        self.assertEqual(summarize_windows([{"kind":"usage","pool":"weekly","before":1,"after":3},{"kind":"usage","pool":"five_hour","before":2,"after":5},{"kind":"usage","pool":"weekly","before":3,"after":4}]), {"weekly":3,"five_hour":3})
    def test_no_mutation(self):
        events = [{"kind":"usage","pool":"weekly","before":1,"after":3}]
        original = [dict(row) for row in events]
        summarize_windows(events)
        self.assertEqual(events, original)
    def test_zero_and_fraction(self):
        self.assertEqual(summarize_windows([{"kind":"usage","pool":"weekly","before":1,"after":1},{"kind":"usage","pool":"weekly","before":1,"after":1.5}]), {"weekly":0.5})
if __name__ == '__main__': unittest.main()
